for mapID,data in pairs(towns) do
    local m=Routing.SHIPPED[mapID]
    if not m then m={};Routing.SHIPPED[mapID]=m end
    for _,key in ipairs({"levels","ways","links","walls"}) do
        m[key]=m[key] or {}
        for _,e in ipairs(data[key] or {}) do m[key][#m[key]+1]=e end
    end
    for _,set in ipairs(data.wallsets or {}) do
        for i,points in ipairs(set.lines) do m.walls[#m.walls+1]={id=set.prefix..i,kind="line",level=set.level,points=points} end
    end
end

